    public BigDecimal calcularAjuste(BigDecimal totalPedido, int numeroParcelas) {
        BigDecimal desconto = totalPedido.multiply(PERCENTUAL_DESCONTO);
        return Arredondamento.arredondar(desconto).negate();
    }

