1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.domain.*;
4	import com.loja.checkout.domain.clube.*;
5	import com.loja.checkout.domain.cupom.*;
6	import com.loja.checkout.domain.entrega.*;
7	import com.loja.checkout.domain.pagamento.*;
8	import com.loja.checkout.model.*;
9	import org.springframework.stereotype.Service;
10	import java.math.BigDecimal;
11	
12	@Service
13	public class ResumoService {
14	    private final RegistroCupons registroCupons;
15	    private final RegistroModalidades registroModalidades;
16	    private final RegistroNiveis registroNiveis;
17	    private final RegistroFormasPagamento registroFormasPagamento;
18	
19	    public ResumoService(
20	        RegistroCupons registroCupons,
21	        RegistroModalidades registroModalidades,
22	        RegistroNiveis registroNiveis,
23	        RegistroFormasPagamento registroFormasPagamento
24	    ) {
25	        this.registroCupons = registroCupons;
26	        this.registroModalidades = registroModalidades;
27	        this.registroNiveis = registroNiveis;
28	        this.registroFormasPagamento = registroFormasPagamento;
29	    }
30	
31	    public Object calcular(PedidoRequest request) {
32	        if (!pedidoValido(request)) {
33	            return new ErroResponse("PEDIDO_INVALIDO");
34	        }
35	
36	        if (request.nivelClube() == null) {
37	            return new ErroResponse("NIVEL_CLUBE_INVALIDO");
38	        }
39	        NivelClube nivelClube = registroNiveis.buscar(request.nivelClube())
40	            .orElse(null);
41	        if (nivelClube == null) {
42	            return new ErroResponse("NIVEL_CLUBE_INVALIDO");
43	        }
44	
45	        if (request.regiao() == null) {
46	            return new ErroResponse("REGIAO_INVALIDA");
47	        }
48	        Regiao regiao;
49	        try {
50	            regiao = Regiao.valueOf(request.regiao());
51	        } catch (IllegalArgumentException e) {
52	            return new ErroResponse("REGIAO_INVALIDA");
53	        }
54	
55	        if (request.modalidadeEntrega() == null) {
56	            return new ErroResponse("MODALIDADE_INVALIDA");
57	        }
58	        ModalidadeEntrega modalidade = registroModalidades.buscar(request.modalidadeEntrega())
59	            .orElse(null);
60	        if (modalidade == null) {
61	            return new ErroResponse("MODALIDADE_INVALIDA");
62	        }
63	
64	        ContextoCalculo contexto = new ContextoCalculo(request.itens());
65	        BigDecimal pesoTotal = contexto.getPesoTotal();
66	
67	        if (!modalidade.estaDisponivel(pesoTotal)) {
68	            return new ErroResponse("MODALIDADE_INDISPONIVEL");
69	        }
70	
71	        BigDecimal subtotalProdutos = calcularSubtotalProdutos(request.itens());
72	        contexto.setSubtotalProdutos(subtotalProdutos);
73	
74	        BigDecimal frete = modalidade.calcularFrete(pesoTotal);
75	        if (nivelClube.freteGratis()) {
76	            frete = BigDecimal.ZERO.setScale(2);
77	        }
78	        contexto.setFrete(frete);
79	
80	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
81	        if (request.cupom() != null && !request.cupom().isBlank()) {
82	            Cupom cupom = registroCupons.buscar(request.cupom()).orElse(null);
83	            if (cupom == null) {
84	                return new ErroResponse("CUPOM_INVALIDO");
85	            }
86	            if (!cupom.aplicavel(contexto)) {
87	                return new ErroResponse("CUPOM_NAO_APLICAVEL");
88	            }
89	            descontoCupom = cupom.calcularDesconto(contexto);
90	        }
91	
92	        BigDecimal seguro = calcularSeguro(subtotalProdutos, regiao);
93	
94	        BigDecimal totalPedido = subtotalProdutos
95	            .subtract(descontoCupom)
96	            .add(frete)
97	            .add(seguro);
98	        totalPedido = Arredondamento.arredondar(totalPedido);
99	
100	        if (request.formaPagamento() == null) {
101	            return new ErroResponse("FORMA_PAGAMENTO_INVALIDA");
102	        }
103	        FormaPagamento formaPagamento = registroFormasPagamento.buscar(request.formaPagamento())
104	            .orElse(null);
105	        if (formaPagamento == null) {
106	            return new ErroResponse("FORMA_PAGAMENTO_INVALIDA");
107	        }
108	
109	        int parcelas = request.parcelas() != null ? request.parcelas() : 1;
110	        if (!formaPagamento.aceitaParcelas(parcelas)) {
111	            return new ErroResponse("PARCELAMENTO_INVALIDO");
112	        }
113	
114	        if (!formaPagamento.estaDisponivel(totalPedido)) {
115	            return new ErroResponse("FORMA_PAGAMENTO_INDISPONIVEL");
116	        }
117	
118	        BigDecimal ajustePagamento = formaPagamento.calcularAjuste(totalPedido, parcelas);
119	        BigDecimal totalFinal = formaPagamento.calcularValorFinal(totalPedido, parcelas);
120	        BigDecimal valorParcela = formaPagamento.calcularValorParcela(totalPedido, parcelas);
121	
122	        BigDecimal creditoProximaCompra = nivelClube.calcularCredito(subtotalProdutos);
123	        boolean brinde = nivelClube.ganhaBrinde(subtotalProdutos);
124	
125	        return new ResumoResponse(
126	            subtotalProdutos,
127	            descontoCupom,
128	            frete,
129	            modalidade.obterPrazo(),
130	            seguro,
131	            ajustePagamento,
132	            totalFinal,
133	            parcelas,
134	            valorParcela,
135	            creditoProximaCompra,
136	            brinde
137	        );
138	    }
139	
140	    private boolean pedidoValido(PedidoRequest request) {
141	        if (request.itens() == null || request.itens().isEmpty()) {
142	            return false;
143	        }
144	        return request.itens().stream().allMatch(ItemCarrinho::valido);
145	    }
146	
147	    private BigDecimal calcularSubtotalProdutos(java.util.List<ItemCarrinho> itens) {
148	        BigDecimal subtotal = itens.stream()
149	            .map(ItemCarrinho::subtotal)
150	            .reduce(BigDecimal.ZERO, BigDecimal::add);
151	        return Arredondamento.arredondar(subtotal);
152	    }
153	
154	    private BigDecimal calcularSeguro(BigDecimal subtotalProdutos, Regiao regiao) {
155	        BigDecimal seguro = subtotalProdutos.multiply(regiao.getPercentualSeguro());
156	        return Arredondamento.arredondar(seguro);
157	    }
158	}
