6	
7	public class Cartao implements FormaPagamento {
8	    private static final BigDecimal TAXA_JUROS_MENSAL = new BigDecimal("0.0199");
9	    private static final int PARCELAS_SEM_JUROS = 3;
10	
11	    @Override
12	    public boolean aceitaParcelas(int numeroParcelas) {
13	        return numeroParcelas >= 1 && numeroParcelas <= 12;
14	    }
15	
16	    @Override
17	    public boolean estaDisponivel(BigDecimal totalPedido) {
18	        return true;
19	    }
20	
21	    @Override
22	    public BigDecimal calcularAjuste(BigDecimal totalPedido, int numeroParcelas) {
23	        BigDecimal valorFinal = calcularValorFinal(totalPedido, numeroParcelas);
24	        return valorFinal.subtract(totalPedido);
25	    }
26	
27	    @Override
28	    public BigDecimal calcularValorFinal(BigDecimal totalPedido, int numeroParcelas) {
29	        if (numeroParcelas <= PARCELAS_SEM_JUROS) {
30	            return totalPedido;
31	        }
32	
33	        BigDecimal valorParcela = calcularValorParcela(totalPedido, numeroParcelas);
34	        BigDecimal valorFinal = valorParcela.multiply(BigDecimal.valueOf(numeroParcelas));
35	        return Arredondamento.arredondar(valorFinal);
36	    }
37	
38	    @Override
39	    public BigDecimal calcularValorParcela(BigDecimal totalPedido, int numeroParcelas) {
40	        if (numeroParcelas <= PARCELAS_SEM_JUROS) {
41	            BigDecimal parcela = totalPedido.divide(
42	                BigDecimal.valueOf(numeroParcelas),
43	                2,
44	                RoundingMode.HALF_EVEN
45	            );
46	            return Arredondamento.arredondar(parcela);
47	        }
48	
49	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_JUROS_MENSAL);
50	        BigDecimal denominador = umMaisTaxa.pow(numeroParcelas);
51	        BigDecimal fator = BigDecimal.ONE.subtract(
52	            BigDecimal.ONE.divide(denominador, 10, RoundingMode.HALF_EVEN)
53	        );
54	
55	        BigDecimal parcela = totalPedido.multiply(TAXA_JUROS_MENSAL)
56	            .divide(fator, 10, RoundingMode.HALF_EVEN);
57	
58	        return Arredondamento.arredondar(parcela);
59	    }
